async (page) => {
  const { request } = require('playwright');
  const ctx = await request.newContext();
  const res = await ctx.get('http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt', {
    headers: { 'Authorization': 'Basic ' + Buffer.from('theagentcompany:theagentcompany').toString('base64') }
  });
  const body = await res.text();
  const fs = require('fs');
  fs.writeFileSync('/tmp/mcp-workspace/command.txt', body);
  return { status: res.status(), body };
}
